mapper.select:
SELECT 
FROM t_user

    delete_flag = 0
    AND username LIKE CONCAT('%', #{username}, '%')
    AND realname LIKE CONCAT('%', #{realname}, '%')
    AND mobile = #{mobile}
    AND email = #{email}
    AND status = #{status}
    AND dept_id = #{deptId}
    AND ssex = #{ssex}

ORDER BY create_time DESC

