mapper.select:
SELECT u.*, ut.status AS userTenantStatus
FROM t_user u
INNER JOIN t_user_tenant ut ON u.user_id = ut.user_id AND ut.tenant_id = #{tenantId}
WHERE u.delete_flag = 0

    AND u.username LIKE CONCAT( #{queryDTO.username}, '%')


    AND u.realname LIKE CONCAT( #{queryDTO.realname}, '%')


    AND u.mobile = #{queryDTO.mobile}


    AND u.id_card_no = #{queryDTO.idCardNo}


    AND u.ssex = #{queryDTO.ssex}


    AND u.status = #{queryDTO.status}
